private const val HEADER="id,name_eng,name_rus,name_arm,synonyms,quantity,unit,location,characteristics_eng,characteristics_rus,characteristics_arm,photo_file,x1,y1,x2,y2\n"
private enum class Lang { ARM, ENG, RUS }
private data class Spot(val file:String,val name:String,val x1:Float,val y1:Float,val x2:Float,val y2:Float)
private data class Item(val id:String,val en:String,val ru:String,val hy:String,val syn:String="",val qty:String="",val unit:String="",val loc:String="",val ce:String="",val cr:String="",val ca:String="",val spots:List<Spot> = emptyList())
