@Composable private fun App(c:Context){
 val db=remember{Db(c)};var all by remember{mutableStateOf(db.load())};var lang by remember{mutableStateOf(db.lang())};var q by remember{mutableStateOf("")};var selected by remember{mutableStateOf<Item?>(null)};var edit by remember{mutableStateOf<Item?>(null)};var report by remember{mutableStateOf<Report?>(null)};var pending by remember{mutableStateOf<Uri?>(null)}
