private class T(val l:Lang){val off get()=when(l){Lang.ARM->"Անցանց կատալոգ";Lang.RUS->"Автономный каталог";else->"Offline catalog"};val imp get()=when(l){Lang.ARM->"Ներմուծել";Lang.RUS->"Импорт";else->"Import"};val template get()=when(l){Lang.ARM->"CSV ձևանմուշ";Lang.RUS->"Шаблон CSV";else->"CSV template"};val search get()=when(l){Lang.ARM->"Փնտրել";Lang.RUS->"Поиск";else->"Search"};val hint get()=when(l){Lang.ARM->"Անուն կամ հոմանիշ՝ ցանկացած լեզվով";Lang.RUS->"Название или синоним на любом языке";else->"Name or synonym in any language"};val empty get()=when(l){Lang.ARM->"Կատալոգը դատարկ է";Lang.RUS->"Каталог пуст";else->"Catalog is empty"};val similar get()=when(l){Lang.ARM->"Նման համընկնում";Lang.RUS->"Похожее совпадение";else->"Similar match"};val done get()=when(l){Lang.ARM->"Ներմուծումն ավարտվեց";Lang.RUS->"Импорт завершён";else->"Import complete"};val add get()=when(l){Lang.ARM->"Նոր";Lang.RUS->"Новых";else->"New"};val update get()=when(l){Lang.ARM->"Թարմացված";Lang.RUS->"Обновлено";else->"Updated"};val close get()=when(l){Lang.ARM->"Փակել";Lang.RUS->"Закрыть";else->"Close"}}
private fun next(x:Lang)=when(x){Lang.ARM->Lang.ENG;Lang.ENG->Lang.RUS;Lang.RUS->Lang.ARM};private fun tag(x:Lang)=when(x){Lang.ARM->"ՀԱՅ";Lang.ENG->"ENG";Lang.RUS->"РУС"};private fun name(i:Item,l:Lang)=when(l){Lang.ARM->i.hy.ifBlank{i.en.ifBlank{i.ru}};Lang.RUS->i.ru.ifBlank{i.en.ifBlank{i.hy}};Lang.ENG->i.en.ifBlank{i.hy.ifBlank{i.ru}}};private fun chars(i:Item,l:Lang)=when(l){Lang.ARM->i.ca.ifBlank{i.ce};Lang.RUS->i.cr.ifBlank{i.ce};Lang.ENG->i.ce.ifBlank{i.ca.ifBlank{i.cr}}}
@Composable private fun Empty(t:T,imp:()->Unit,tem:()->Unit){Column(Modifier.fillMaxWidth().padding(top=70.dp),horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Default.Image,null,Modifier.size(52.dp),Color(0xff166534));Spacer(Modifier.height(12.dp));Text(t.empty,fontWeight=FontWeight.Bold);Text("Select the CSV, then choose one or more pictures from your phone.",Modifier.padding(16.dp),color=Color.Gray);Button(onClick=imp){Text(t.imp)};TextButton(onClick=tem){Text(t.template)}}}
private fun normalize(s:String)=s.lowercase(Locale.ROOT).replace(Regex("[^\\p{L}\\p{N}]+")," ").trim()
private fun search(xs:List<Item>,q:String):List<Pair<Item,Boolean>>{val n=normalize(q);if(n.isBlank())return xs.sortedBy{it.en}.map{it to false};return xs.mapNotNull{i->val f=listOf(i.en,i.ru,i.hy)+i.syn.split(';');val exact=f.any{normalize(it)==n};val part=f.any{normalize(it).contains(n)||n.contains(normalize(it))};val d=f.filter{it.isNotBlank()}.minOfOrNull{lev(normalize(it),n)}?:99;when{exact->Triple(i,false,100);part->Triple(i,false,70);d<=max(2,n.length/3)->Triple(i,true,40-d);else->null}}.sortedByDescending{it.third}.map{it.first to it.second}}
private fun lev(a:String,b:String):Int{var p=IntArray(b.length+1){it};for(i in a.indices){val c=IntArray(b.length+1);c[0]=i+1;for(j in b.indices)c[j+1]=minOf(c[j]+1,p[j+1]+1,p[j]+if(a[i]==b[j])0 else 1);p=c};return p[b.length]}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun Detail(i:Item,l:Lang,t:T,back:()->Unit,edit:()->Unit){var photo by remember{mutableStateOf<Spot?>(null)};Surface(Modifier.fillMaxSize(),color=Color(0xfff8faf8)){Column{TopAppBar(title={Column{Text(name(i,l),maxLines=1,overflow=TextOverflow.Ellipsis);Text(i.id,style=MaterialTheme.typography.labelSmall)}},navigationIcon={IconButton(onClick=back){Icon(Icons.Default.ArrowBack,t.close)}},actions={TextButton(onClick=edit){Text("Edit")}});LazyColumn(Modifier.padding(horizontal=16.dp),contentPadding=PaddingValues(bottom=24.dp)){item{block("Quantity",listOf(i.qty,i.unit).filter{it.isNotBlank()}.joinToString(" "));block("Location",i.loc);block("Characteristics",chars(i,l));block("Synonyms",i.syn);Text("Photos",Modifier.padding(top=12.dp),fontWeight=FontWeight.Bold)};items(i.spots){s->Card(Modifier.fillMaxWidth().padding(top=8.dp).clickable{photo=s}){Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Image,null);Spacer(Modifier.width(10.dp));Text(s.name,Modifier.weight(1f),maxLines=1,overflow=TextOverflow.Ellipsis)}}}}}};photo?.let{s->Photo(s){photo=null}}}
@Composable private fun block(title:String,value:String){if(value.isNotBlank())Column(Modifier.padding(top=12.dp)){Text(title,style=MaterialTheme.typography.labelSmall,color=Color.Gray);Text(value)}}
@Composable private fun Photo(s:Spot,close:()->Unit){val b=remember(s.file){BitmapFactory.decodeFile(s.file)};AlertDialog(onDismissRequest=close,title={Text(s.name)},text={ if(b==null) Text("Image file unavailable") else Viewer(b,s) },confirmButton={TextButton(onClick=close){Text("Close")}})}
@Composable private fun Viewer(b:android.graphics.Bitmap,s:Spot){var z by remember{mutableFloatStateOf(1f)};var dx by remember{mutableFloatStateOf(0f)};var dy by remember{mutableFloatStateOf(0f)};Box(Modifier.fillMaxWidth().aspectRatio(b.width.toFloat()/b.height).clip(RoundedCornerShape(8.dp)).background(Color.Black).pointerInput(Unit){detectTransformGestures{_,pan,zoom,_->z=(z*zoom).coerceIn(1f,5f);dx+=pan.x;dy+=pan.y}}){Box(Modifier.fillMaxSize().graphicsLayer(scaleX=z,scaleY=z,translationX=dx,translationY=dy)){Image(b.asImageBitmap(),null,Modifier.fillMaxSize(),contentScale=ContentScale.FillBounds);Canvas(Modifier.fillMaxSize()){drawRect(Color(0xffffd54f),Offset(size.width*s.x1/b.width,size.height*s.y1/b.height),Size(size.width*(s.x2-s.x1)/b.width,size.height*(s.y2-s.y1)/b.height),style=Stroke(4f))}}}}
@Composable private fun Editor(i:Item,t:T,dismiss:()->Unit,save:(Item)->Unit){var en by remember{mutableStateOf(i.en)};var ru by remember{mutableStateOf(i.ru)};var hy by remember{mutableStateOf(i.hy)};var syn by remember{mutableStateOf(i.syn)};var qty by remember{mutableStateOf(i.qty)};var unit by remember{mutableStateOf(i.unit)};var loc by remember{mutableStateOf(i.loc)};var ce by remember{mutableStateOf(i.ce)};var cr by remember{mutableStateOf(i.cr)};var ca by remember{mutableStateOf(i.ca)};AlertDialog(onDismissRequest=dismiss,title={Text("Edit ${i.id}")},text={LazyColumn(Modifier.heightIn(max=430.dp)){item{field("English name",en){en=it};field("Русское название",ru){ru=it};field("Հայերեն անուն",hy){hy=it};field("Synonyms (;)",syn){syn=it};field("Quantity",qty){qty=it};field("Unit",unit){unit=it};field("Location",loc){loc=it};field("Characteristics (English)",ce){ce=it};field("Характеристики",cr){cr=it};field("Բնութագրեր",ca){ca=it}}}},confirmButton={TextButton(onClick={save(i.copy(en=en,ru=ru,hy=hy,syn=syn,qty=qty,unit=unit,loc=loc,ce=ce,cr=cr,ca=ca))}){Text("Save")}},dismissButton={TextButton(onClick=dismiss){Text("Cancel")}})}
@Composable private fun field(l:String,v:String,set:(String)->Unit){OutlinedTextField(v,set,Modifier.fillMaxWidth().padding(vertical=2.dp),label={Text(l)})}

private class Db(private val c:Context){private val p=c.getSharedPreferences("stock",0);private val dir=File(c.filesDir,"images").apply{mkdirs()};fun lang()=runCatching{Lang.valueOf(p.getString("lang",Lang.ARM.name)!!)}.getOrDefault(Lang.ARM);fun saveLang(l:Lang){p.edit().putString("lang",l.name).apply()};fun load()=runCatching{val a=JSONArray(p.getString("items","[]"));List(a.length()){from(a.getJSONObject(it))}}.getOrDefault(emptyList());private fun save(x:List<Item>){p.edit().putString("items",JSONArray(x.map{json(it)}).toString()).apply()};fun manual(i:Item){save(load().map{if(it.id==i.id)i else it})}
 fun import(csv:Uri,photos:List<Uri>):Report{val er=mutableListOf<String>();val no=mutableListOf<String>();val fs=photos.map{ChosenPhoto(it,fileName(it))};if(fs.isEmpty())return Report(0,0,listOf("No images found in folder."),emptyList());val lines=c.contentResolver.openInputStream(csv)?.bufferedReader()?.readLines().orEmpty();if(lines.size<2)return Report(0,0,listOf("CSV has no data rows."),emptyList());val h=line(lines[0]).map{header(it)};val ix=h.withIndex().associate{it.value to it.index};val idColumn=h.indexOfFirst{it=="id"||it=="item_id"||it=="itemid"};if(idColumn<0)return Report(0,0,listOf("Required ID column is missing. Headers: "+h.joinToString()),emptyList());fun g(r:List<String>,k:String)=(if(k=="id")idColumn else ix[k])?.let{r.getOrElse(it){""}.trim()}.orEmpty()
val map=load().associateBy{it.id}.toMutableMap();val loaded=linkedMapOf<String,Item>();var a=0;var u=0;lines.drop(1).forEachIndexed{n,raw->if(raw.isBlank())return@forEachIndexed;val r=line(raw);val id=g(r,"id");val en=g(r,"name_eng");val ru=g(r,"name_rus");val hy=g(r,"name_arm");if(id.isBlank()||(en.isBlank()&&ru.isBlank()&&hy.isBlank())){er+="Row ${n+2}: id and one name are required.";return@forEachIndexed};val fn=g(r,"photo_file");val f=if(fn.isBlank()&&fs.size==1)fs[0] else fs.firstOrNull{it.name.equals(fn,true)};if(f==null){er+="Row ${n+2}: image not found.";return@forEachIndexed};val co=listOf("x1","y1","x2","y2").map{g(r,it).toFloatOrNull()};if(co.any{it==null}||co[2]!!<=co[0]!!||co[3]!!<=co[1]!!||co.any{it!!<0}){er+="Row ${n+2}: invalid coordinates.";return@forEachIndexed};val out=copy(f.uri,f.name)?:run{er+="Row ${n+2}: image copy failed.";return@forEachIndexed};val spot=Spot(out.absolutePath,f.name?:fn,co[0]!!,co[1]!!,co[2]!!,co[3]!!);val old=loaded[id]?:map[id];loaded[id]=Item(id,en,ru,hy,g(r,"synonyms"),g(r,"quantity"),g(r,"unit"),g(r,"location"),g(r,"characteristics_eng"),g(r,"characteristics_rus"),g(r,"characteristics_arm"),(old?.spots.orEmpty()+spot).distinctBy{"${it.file}/${it.x1}/${it.y1}/${it.x2}/${it.y2}"})};loaded.forEach{(id,i)->if(map.containsKey(id))u++ else a++;map[id]=i};save(map.values.sortedBy{it.id});if(ix["photo_file"]==null&&fs.size==1)no+="No photo_file column: used ${fs[0].name}.";return Report(a,u,er,no)}
 private fun fileName(uri:Uri):String{var n="image";c.contentResolver.query(uri,null,null,null,null)?.use{q->if(q.moveToFirst())n=q.getString(q.getColumnIndexOrThrow(OpenableColumns.DISPLAY_NAME))};return n};private fun copy(uri:Uri,name:String)=runCatching{val target=File(dir,uri.hashCode().toString()+"_"+name.replace(Regex("[^A-Za-z0-9._-]"),"_"));if(!target.exists())c.contentResolver.openInputStream(uri)?.use{input->target.outputStream().use{input.copyTo(it)}};target.takeIf{it.exists()}}.getOrNull()
 private fun json(i:Item)=JSONObject().put("id",i.id).put("en",i.en).put("ru",i.ru).put("hy",i.hy).put("syn",i.syn).put("qty",i.qty).put("unit",i.unit).put("loc",i.loc).put("ce",i.ce).put("cr",i.cr).put("ca",i.ca).put("spots",JSONArray(i.spots.map{s->JSONObject().put("f",s.file).put("n",s.name).put("x1",s.x1).put("y1",s.y1).put("x2",s.x2).put("y2",s.y2)}))
 private fun from(o:JSONObject):Item{val a=o.optJSONArray("spots")?:JSONArray();return Item(o.getString("id"),o.optString("en"),o.optString("ru"),o.optString("hy"),o.optString("syn"),o.optString("qty"),o.optString("unit"),o.optString("loc"),o.optString("ce"),o.optString("cr"),o.optString("ca"),List(a.length()){n->a.getJSONObject(n).let{s->Spot(s.getString("f"),s.optString("n"),s.getDouble("x1").toFloat(),s.getDouble("y1").toFloat(),s.getDouble("x2").toFloat(),s.getDouble("y2").toFloat())}})} }
private fun header(s:String)=s.removePrefix("\uFEFF").trim().lowercase(Locale.ROOT).replace(Regex("[\\s-]+"),"_")
private fun line(s:String):List<String>{val sep=if(s.count{it==';'}>s.count{it==','})';' else if(s.count{it=='\t'}>s.count{it==','})'\t' else ',';val o=mutableListOf<String>();val b=StringBuilder();var q=false;var i=0;while(i<s.length){val c=s[i];if(c=='"'){if(q&&i+1<s.length&&s[i+1]=='"'){b.append(c);i++}else q=!q}else if(c==sep&&!q){o+=b.toString();b.clear()}else b.append(c);i++};o+=b.toString();return o}
